45	function NarrowNotSupported({
46	  redirectTo = '/budget',
47	  children,
48	}: {
49	  redirectTo?: string;
50	  children: ReactElement;
51	}) {
52	  const { isNarrowWidth } = useResponsive();
53	  const navigate = useNavigate();
54	  useEffect(() => {
55	    if (isNarrowWidth) {
56	      void navigate(redirectTo);
57	    }
58	  }, [isNarrowWidth, navigate, redirectTo]);
59	  return isNarrowWidth ? null : children;
60	}
61	
62	function WideNotSupported({
63	  children,
64	  redirectTo = '/budget',
65	}: {
66	  redirectTo?: string;
67	  children: ReactElement;
68	}) {
69	  const { isNarrowWidth } = useResponsive();
70	  const navigate = useNavigate();
71	  useEffect(() => {
72	    if (!isNarrowWidth) {
73	      void navigate(redirectTo);
74	    }
75	  }, [isNarrowWidth, navigate, redirectTo]);
76	  return isNarrowWidth ? children : null;
77	}
