535	export function BudgetFileSelection({
536	  showHeader = true,
537	  quickSwitchMode = false,
538	}: BudgetFileSelectionProps) {
539	  const dispatch = useDispatch();
540	  const allFiles = useSelector(state => state.budgetfiles.allFiles || []);
541	  const multiuserEnabled = useMultiuserEnabled();
542	  const [id] = useMetadataPref('id');
543	  const [currentUserId, setCurrentUserId] = useState('');
544	  const userData = useSelector(state => state.user.data);
545	  const serverStatus = useSyncServerStatus();
546	
547	  const fetchUsers = useCallback(async () => {
548	    try {
549	      setCurrentUserId(userData?.userId ?? '');
550	    } catch (error) {
551	      console.error('Failed to fetch users:', error);
552	    }
553	  }, [userData?.userId]);
554	
555	  useEffect(() => {
556	    if (multiuserEnabled && !userData?.offline) {
557	      void fetchUsers();
558	    }
559	  }, [multiuserEnabled, userData?.offline, fetchUsers]);
560	
561	  // Remote files do not have the 'id' field
562	  function isNonRemoteFile(
563	    file: File,
564	  ): file is LocalFile | SyncableLocalFile | SyncedLocalFile {
565	    return file.state !== 'remote';
566	  }
567	
568	  // Filter out the open file
569	  const files = id
570	    ? allFiles.filter(file => !isNonRemoteFile(file) || file.id !== id)
571	    : allFiles;
572	
573	  const [creating, setCreating] = useState(false);
574	  const { isNarrowWidth } = useResponsive();
575	  const narrowButtonStyle = isNarrowWidth
576	    ? {
577	        height: styles.mobileMinHeight,
