727	function UserAccessForFile({ fileId, currentUserId }: UserAccessForFileProps) {
728	  const { t } = useTranslation();
729	
730	  const allFiles = useSelector(state => state.budgetfiles.allFiles || []);
731	  const remoteFiles = allFiles.filter(
732	    f => f.state === 'remote' || f.state === 'synced' || f.state === 'detached',
733	  ) as (SyncedLocalFile | RemoteFile)[];
734	  const currentFile = remoteFiles.find(f => f.cloudFileId === fileId);
735	  const multiuserEnabled = useMultiuserEnabled();
736	
737	  let usersAccess = currentFile?.usersWithAccess ?? [];
738	  usersAccess = usersAccess?.filter(user => user.userName !== '') ?? [];
739	
740	  const sortedUsersAccess = [...usersAccess].sort((a, b) => {
741	    const textA =
742	      a.userId === currentUserId ? t('You') : (a.displayName ?? a.userName);
743	    const textB =
744	      b.userId === currentUserId ? t('You') : (b.displayName ?? b.userName);
745	    return textA.localeCompare(textB);
746	  });
747	
748	  return (
749	    <View>
750	      {multiuserEnabled &&
751	        usersAccess.length > 0 &&
752	        !(sortedUsersAccess.length === 1 && sortedUsersAccess[0].owner) && (
753	          <View
754	            style={{
755	              marginLeft: '5px',
756	              alignSelf: 'center',
757	            }}
758	          >
759	            <Tooltip
760	              content={
761	                <View
762	                  style={{
763	                    margin: 5,
764	                  }}
765	                >
766	                  <Text
767	                    style={{
768	                      ...styles.altMenuHeaderText,
769	                      ...styles.verySmallText,
770	                      color: theme.pageTextLight,
